<script setup lang="ts">
import { ref, computed, watch, onUnmounted } from 'vue'
import { useRoute } from 'vue-router'
import { get, mutate, ApiError } from '../api/client'
import { useAuthStore } from '../stores/auth'
import type { Page, Entity } from '../types/catalog'
import Pager from '../components/Pager.vue'
import { relationDefinitions } from '../utils/characterGraph'
const route = useRoute(), auth = useAuthStore()
type Row = Record<string, unknown>
const section = computed(() => String(route.params.section || 'imports'))
const titles: Record<string, string> = { entities: '实体档案', relations: '关系维护', imports: '数据导入', users: '用户权限', logs: '操作日志' }
const result = ref<Page<Row>>(), records = ref<Page<Row>>(), task = ref<Row>(), loading = ref(false), saving = ref(false), error = ref(''), message = ref(''), page = ref(1), keyword = ref(''), entityType = ref('ANIME'), relationType = ref(''), status = ref(''), recordStatus = ref('FAILED')
interface EditForm { spoiler: boolean; ended: boolean; sourceUrl: string; type: string; name: string; nameCn: string; summary: string; year: string; format: string; active: boolean; fromUid: string; toUid: string; roleCode: string; roleName: string; animeUid: string; relationCode: string; evidence: string; description: string; label: string; username: string; displayName: string; password: string; admin: boolean; enabled: boolean }
const editing = ref<Row | null>(null), showForm = ref(false), file = ref<File>(), form = ref<EditForm>({} as EditForm), stats = ref<{ entities: { count: number }[]; relations: { count: number }[]; users: number }>()
let timer: ReturnType<typeof setTimeout> | undefined, controller: AbortController | undefined
const taskId = computed(() => route.params.id ? Number(route.params.id) : undefined)
const taskActive = computed(() => ['PENDING', 'RUNNING'].includes(String(task.value?.status)))
const retryable = (row: Row) => ['FAILED', 'PARTIAL_FAILED', 'INTERRUPTED'].includes(String(row.status))
const endpoint = (row: Row, field: string) => { const value = row[field]; return value && typeof value === 'object' ? String((value as Entity).nameCn || (value as Entity).name || (value as Entity).uid) : String(value || '') }
const displayStatus = (value: unknown) => ({ PENDING: '等待中', RUNNING: '导入中', SUCCEEDED: '已成功', FAILED: '失败', PARTIAL_FAILED: '部分失败', INTERRUPTED: '已中断' } as Record<string, string>)[String(value)] || String(value)
async function load(nextPage = page.value) {
  clearTimeout(timer); controller?.abort(); controller = new AbortController(); const current = controller; page.value = nextPage; loading.value = true; error.value = ''
  try {
    if (taskId.value) { task.value = await get<Row>(`/admin/imports/${taskId.value}`, current.signal); records.value = await get<Page<Row>>(`/admin/imports/${taskId.value}/records?${new URLSearchParams({ status: recordStatus.value, page: String(page.value) })}`, current.signal); if (taskActive.value) timer = setTimeout(() => load(), 2500) }
    else { task.value = undefined; const params = new URLSearchParams({ page: String(page.value) }); if (section.value === 'entities') { params.set('type', entityType.value); params.set('keyword', keyword.value) } if (section.value === 'relations' && relationType.value) params.set('type', relationType.value); if (status.value && ['entities', 'relations'].includes(section.value)) params.set('active', status.value); result.value = await get<Page<Row>>(`/admin/${section.value}?${params}`, current.signal) }
  } catch(e) { if (!current.signal.aborted) { error.value = e instanceof Error ? e.message : '读取失败'; if (e instanceof ApiError && e.status === 401) { auth.user = null } } }
  finally { if (!current.signal.aborted) loading.value = false }
}
watch(() => route.fullPath, () => { showForm.value = false; message.value = ''; page.value = 1; load(1) }, { immediate: true })
get<typeof stats.value>('/admin/stats').then(value => stats.value = value).catch(() => {})
onUnmounted(() => { clearTimeout(timer); controller?.abort() })
function open(row: Row | null = null) {
  editing.value = row; showForm.value = true; message.value = ''; error.value = ''
  const props = row?.properties as Row | undefined
  form.value = { spoiler: props?.spoiler === true, ended: props?.ended === true, sourceUrl: String(props?.sourceUrl || ''), type: String(row?.type || entityType.value), name: String(row?.name || ''), nameCn: String(row?.nameCn || ''), summary: String(row?.summary || ''), year: String(row?.year || ''), format: String(row?.format || ''), active: row?.active !== false, fromUid: '', toUid: '', roleCode: '', roleName: '', animeUid: '', relationCode: '', evidence: '', description: String(props?.description || ''), label: String(props?.label || ''), username: String(row?.username || ''), displayName: String(row?.displayName || ''), password: '', admin: Array.isArray(row?.roles) && row!.roles.includes('ADMIN'), enabled: row?.enabled !== false }
  if(section.value === 'relations') { form.value.type = String(row?.type || 'PARTICIPATED_IN'); form.value.active = props?.active !== false; form.value.evidence = String(props?.evidence || '') }
}
async function action(callback: () => Promise<unknown>, success: string) { saving.value = true; error.value = ''; message.value = ''; try { await callback(); showForm.value = false; message.value = success; await load() } catch(e) { error.value = e instanceof Error ? e.message : '操作失败' } finally { saving.value = false } }
function save() {
  action(async () => {
    const f = form.value
    if (section.value === 'entities') { const data = { name: f.name, nameCn: f.nameCn || null, summary: f.summary || null, ...(f.year ? { year: Number(f.year) } : {}), format: f.format || null }; return editing.value ? mutate(`/admin/entities/${encodeURIComponent(String(editing.value.uid))}`, 'PATCH', { ...data, active: f.active }) : mutate('/admin/entities', 'POST', { ...data, type: f.type }) }
    if (section.value === 'relations') {
      if (editing.value) return mutate(`/admin/relations/${encodeURIComponent(String(editing.value.uid))}`, 'PATCH', { active: f.active, properties: { description: f.description, label: f.label, ...(f.type === 'CHARACTER_RELATION' ? { evidence: f.evidence, spoiler: f.spoiler, ended: f.ended, sourceUrl: f.sourceUrl } : {}) } })
      const properties: Row = { description: f.description, label: f.label }
      if (f.type === 'PARTICIPATED_IN') { properties.roleCode = f.roleCode; properties.roleName = f.roleName }
      if (['VOICED', 'CHARACTER_RELATION'].includes(String(f.type))) properties.animeUid = f.animeUid
      if (f.type === 'VOICED') properties.scopeKnown = Boolean(f.animeUid)
      if (['RELATED_TO', 'CHARACTER_RELATION'].includes(String(f.type))) properties.relationCode = f.relationCode
      if (f.type === 'CHARACTER_RELATION') { properties.evidence = f.evidence; properties.sourceName = '管理员维护'; properties.spoiler = f.spoiler; properties.ended = f.ended; properties.sourceUrl = f.sourceUrl }
      return mutate('/admin/relations', 'POST', { type: f.type, fromUid: f.fromUid, toUid: f.toUid, properties })
    }
    if (section.value === 'users') { const data = { displayName: f.displayName, roles: f.admin ? ['ADMIN', 'USER'] : ['USER'], enabled: f.enabled }; if (editing.value) { await mutate(`/admin/users/${editing.value.id}`, 'PATCH', data); if (f.password) await mutate(`/admin/users/${editing.value.id}/reset-password`, 'POST', { password: f.password }); return }; return mutate('/admin/users', 'POST', { ...data, username: f.username, password: f.password }) }
  }, '保存成功')
}
async function upload() { if (!file.value) return; const data = new FormData(); data.append('file', file.value); await action(() => mutate('/admin/imports', 'POST', data), '导入任务已创建，可打开任务查看进度') }
function retry(row: Row) { action(() => mutate(`/admin/imports/${row.id}/retry`, 'POST'), '已创建重试任务') }
</script>
<template><section class="page-intro"><p class="eyebrow">WORKSPACE · 管理工作台</p><h1>{{ titles[section] || '管理工作台' }}</h1><p>维护公开档案与关系，追踪导入结果。停用的数据会从公开查询中隐藏。</p><div class="tabs"><RouterLink v-for="(name, code) in titles" :key="code" :to="`/admin/${code}`">{{ name }}</RouterLink></div></section><div v-if="stats" class="stats-strip"><span>实体 <b>{{ stats.entities.reduce((n, x) => n + x.count, 0) }}</b></span><span>关系 <b>{{ stats.relations.reduce((n, x) => n + x.count, 0) }}</b></span><span>账户 <b>{{ stats.users }}</b></span></div><p v-if="error" class="feedback error" role="alert">{{ error }} <button @click="load()">重新读取</button><RouterLink v-if="!auth.user" to="/login">重新登录</RouterLink></p><p v-if="message" class="feedback" role="status">{{ message }}</p>
<section v-if="section === 'imports' && !taskId" class="panel"><h2>上传标准数据包</h2><p class="muted">选择项目标准 JSON 文件。每个文件最多 20MB、50,000 条记录。记录失败可查看原因并重试，重复导入会更新已有记录。</p><form class="toolbar" @submit.prevent="upload"><label class="grow">数据文件<input type="file" accept=".json,application/json" required @change="file = ($event.target as HTMLInputElement).files?.[0]"></label><button class="primary" :disabled="saving || !file">{{ saving ? '正在上传…' : '开始导入' }}</button></form></section>
<template v-if="taskId && task"><RouterLink to="/admin/imports" class="button">← 返回任务列表</RouterLink><section class="panel"><h2>导入任务 #{{ task.id }} · {{ displayStatus(task.status) }}</h2><p>来源 {{ task.source }} · 处理 {{ task.checkpoint }} / {{ task.totalCount }} 条</p><progress :value="Number(task.checkpoint)" :max="Number(task.totalCount)"></progress><p>成功 {{ task.successCount }} · 失败 {{ task.failedCount }}</p><p v-if="task.errorSummary" class="error">{{ task.errorSummary }}</p><button v-if="retryable(task)" @click="retry(task)" :disabled="saving">重试此文件</button><p v-if="taskActive" class="muted">进度每 2.5 秒更新一次。</p></section><section class="panel"><div class="toolbar"><label>记录筛选<select v-model="recordStatus" @change="load(1)"><option value="FAILED">失败记录</option><option value="">全部记录</option><option value="SUCCEEDED">成功记录</option><option value="PENDING">等待记录</option></select></label></div><div v-for="row in records?.items" :key="String(row.id)" class="data-row"><span>{{ row.recordKey }} · {{ row.recordType }}</span><span>{{ displayStatus(row.status) }}</span><span class="error">{{ row.errorMessage }}</span></div><p v-if="!records?.items.length" class="muted">暂无符合条件的记录。</p><Pager v-if="records" :page="records.page" :total="records.total" :size="records.pageSize" @change="load" /></section></template>
<template v-else><form v-if="['entities', 'relations', 'users'].includes(section)" class="toolbar" @submit.prevent="load(1)"><template v-if="section === 'entities'"><label>实体类型<select v-model="entityType"><option value="ANIME">动画作品</option><option value="PERSON">制作人员</option><option value="CHARACTER">角色</option></select></label><label class="grow">名称<input v-model="keyword" placeholder="按名称搜索"></label></template><label v-if="section === 'relations'">关系类型<select v-model="relationType"><option value="">全部</option><option>PARTICIPATED_IN</option><option>APPEARS_IN</option><option>VOICED</option><option>RELATED_TO</option><option>CHARACTER_RELATION</option></select></label><label v-if="section !== 'users'">状态<select v-model="status"><option value="">全部</option><option value="true">启用</option><option value="false">停用</option></select></label><button>筛选</button><button type="button" class="primary" @click="open()">新增{{ section === 'users' ? '账户' : section === 'relations' ? '关系' : '档案' }}</button></form>
<section v-if="showForm" class="panel edit-panel"><div class="section-heading"><h2>{{ editing ? '编辑' : '新增' }}{{ titles[section] }}</h2><button @click="showForm = false">取消</button></div><form class="form-grid" @submit.prevent="save"><template v-if="section === 'entities'"><label v-if="!editing">实体类型<select v-model="form.type"><option value="ANIME">动画作品</option><option value="PERSON">制作人员</option><option value="CHARACTER">角色</option></select></label><label>名称<input v-model="form.name" required maxlength="1000"></label><label>中文名<input v-model="form.nameCn" maxlength="1000"></label><label v-if="form.type === 'ANIME'">年份<input v-model="form.year" type="number" min="1800" max="2200"></label><label v-if="form.type === 'ANIME'">形式<input v-model="form.format" placeholder="TV / 剧场版 / OVA"></label><label class="full-width">简介<textarea v-model="form.summary" rows="5" maxlength="20000"></textarea></label></template>
<template v-if="section === 'relations'"><template v-if="!editing"><label>关系类型<select v-model="form.type"><option value="PARTICIPATED_IN">人员 → 作品：制作</option><option value="APPEARS_IN">角色 → 作品：出场</option><option value="VOICED">人员 → 角色：配音</option><option value="RELATED_TO">作品 → 作品：关联</option><option value="CHARACTER_RELATION">角色 → 角色：剧情</option></select></label><label>起点标识<input v-model="form.fromUid" required placeholder="从档案中复制稳定标识"></label><label>终点标识<input v-model="form.toUid" required placeholder="从档案中复制稳定标识"></label><template v-if="form.type === 'PARTICIPATED_IN'"><label>岗位代码<input v-model="form.roleCode" required placeholder="DIRECTOR / SCRIPT"></label><label>岗位名称<input v-model="form.roleName" placeholder="监督 / 脚本"></label></template><label v-if="['VOICED', 'CHARACTER_RELATION'].includes(String(form.type))">作品标识<input v-model="form.animeUid" :required="form.type === 'CHARACTER_RELATION'" placeholder="配音留空表示范围未知"></label><label v-if="form.type === 'CHARACTER_RELATION'">剧情关系<select v-model="form.relationCode" required><option v-for="type in relationDefinitions.filter(t => !t.legacy)" :key="type.code" :value="type.code">{{ type.label }}{{ type.directed ? '（起点具有此身份）' : '（无方向）' }}</option></select></label><label v-if="form.type === 'RELATED_TO'">关联代码<input v-model="form.relationCode" required placeholder="SEQUEL / PREQUEL"></label></template><label>显示名称<input v-model="form.label"></label><label class="full-width">关系说明<textarea v-model="form.description" rows="3"></textarea></label><template v-if="form.type === 'CHARACTER_RELATION'"><label class="inline-check"><input v-model="form.spoiler" type="checkbox">包含剧透</label><label class="inline-check"><input v-model="form.ended" type="checkbox">关系已结束</label><label class="full-width">来源链接<input v-model="form.sourceUrl" type="url" placeholder="https://…"></label></template><label v-if="form.type === 'CHARACTER_RELATION'" class="full-width">出处与证据<textarea v-model="form.evidence" required rows="3"></textarea></label></template>
<template v-if="section === 'users'"><label v-if="!editing">用户名<input v-model="form.username" required minlength="3" maxlength="50" pattern="[a-zA-Z0-9_.-]+" autocomplete="off"></label><label>显示名称<input v-model="form.displayName" maxlength="100"></label><label>{{ editing ? '重设密码（留空保留）' : '初始密码' }}<input v-model="form.password" type="password" :required="!editing" minlength="12" maxlength="72" autocomplete="new-password"></label><label class="inline-check"><input v-model="form.admin" type="checkbox">管理员权限</label><label class="inline-check"><input v-model="form.enabled" type="checkbox">启用账户</label></template><label v-if="editing && section !== 'users'" class="inline-check"><input v-model="form.active" type="checkbox">启用该记录</label><div class="full-width"><button class="primary" :disabled="saving">{{ saving ? '正在保存…' : '保存修改' }}</button></div></form></section>
<p v-if="loading" class="feedback" role="status">正在读取记录…</p><div v-if="result" class="panel"><div class="table-scroll"><table><thead><tr><template v-if="section === 'imports'"><th>任务</th><th>来源</th><th>状态</th><th>成功 / 总数</th><th>操作</th></template><template v-else-if="section === 'entities'"><th>名称</th><th>稳定标识</th><th>状态</th><th>操作</th></template><template v-else-if="section === 'relations'"><th>起点 → 终点</th><th>关系</th><th>状态</th><th>操作</th></template><template v-else-if="section === 'users'"><th>用户名</th><th>显示名</th><th>角色</th><th>状态</th><th>操作</th></template><template v-else><th>动作</th><th>目标</th><th>说明</th><th>时间</th></template></tr></thead><tbody><tr v-for="row in result.items" :key="String(row.id || row.uid)"><template v-if="section === 'imports'"><td>#{{ row.id }}</td><td>{{ row.source }}</td><td>{{ displayStatus(row.status) }}</td><td>{{ row.successCount }} / {{ row.totalCount }}</td><td><RouterLink class="button" :to="`/admin/imports/${row.id}`">查看进度</RouterLink><button v-if="retryable(row)" @click="retry(row)" :disabled="saving">重试</button></td></template><template v-else-if="section === 'entities'"><td>{{ row.nameCn || row.name }}</td><td><small>{{ row.uid }}</small></td><td>{{ row.active ? '启用' : '停用' }}</td><td><button @click="open(row)">编辑</button></td></template><template v-else-if="section === 'relations'"><td>{{ endpoint(row, 'source') }} → {{ endpoint(row, 'target') }}</td><td>{{ row.type }}</td><td>{{ (row.properties as Row)?.active ? '启用' : '停用' }}</td><td><button @click="open(row)">编辑</button></td></template><template v-else-if="section === 'users'"><td>{{ row.username }}</td><td>{{ row.displayName }}</td><td>{{ Array.isArray(row.roles) ? row.roles.join('、') : '' }}</td><td>{{ row.enabled ? '启用' : '停用' }}</td><td><button @click="open(row)">编辑权限</button></td></template><template v-else><td>{{ row.action }}</td><td>{{ row.target_uid }}</td><td>{{ row.summary }}</td><td>{{ row.created_at }}</td></template></tr></tbody></table></div><p v-if="!result.items.length" class="empty-state">暂无记录。</p><Pager :page="result.page" :total="result.total" :size="result.pageSize" :loading="loading" @change="load" /></div></template></template>
